const prompt = msg.prompt || (typeof msg.payload === 'string' ? msg.payload : JSON.stringify(msg.payload));
let cmd = `agy -p ${JSON.stringify(prompt)} --dangerously-skip-permissions`;
if (msg.schema) {
    const schemaStr = typeof msg.schema === 'object' ? JSON.stringify(msg.schema) : msg.schema;
    cmd += ` --json-schema ${JSON.stringify(schemaStr)} --output-format json`;
}
msg.payload = cmd;
return msg;

let parsed;
try {
    parsed = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload;
} catch (e) {
    parsed = { response: msg.payload };
}
let result = parsed.structured_output;
if (!result && parsed.response) {
    try { result = typeof parsed.response === 'string' ? JSON.parse(parsed.response) : parsed.response; } catch (e) { result = parsed.response; }
}
msg.payload = result || parsed;
return msg;

const text = JSON.stringify(msg.payload);
const hash = crypto.createHash('md5').update(text).digest('hex');
const cache = flow.get('e2e_cache') || {};
if (cache[hash] && Date.now() - cache[hash].timestamp < 3600 * 1000) {
    msg.payload = cache[hash].data; msg.fromCache = true;
    return [msg, null];
}
const activeCount = flow.get('active_e2e_ai') || 0;
if (activeCount >= 1) {
    node.warn('🛑 [並行保護] 任務進入降級佇列');
    msg.payload = { status: 'THROTTLED', reason: 'AI 名額已滿', cache_key: hash };
    return [null, msg];
}
flow.set('active_e2e_ai', activeCount + 1);
msg.hash = hash;
msg.prompt = `請以繁體中文一句話解釋以下系統事件：${text}`;
msg.schema = { type: 'object', properties: { summary: { type: 'string' } }, required: ['summary'] };
return [null, msg];

flow.set('active_e2e_ai', 0);
const hash = msg.hash;
if (hash) {
    const cache = flow.get('e2e_cache') || {};
    cache[hash] = { data: msg.payload, timestamp: Date.now() };
    flow.set('e2e_cache', cache);
}
node.status({ fill: 'blue', shape: 'dot', text: '已釋放鎖並寫入快取' });
return msg;
